oxy_webhelp_navlinks = {"aws_configuration_cloud_acc-d39536e16685":{"topics":[{"title":"Adding a self-managed AWS account using a template for protection","shortdesc":"<p class=\"shortdesc\">To protect AWS resources within an individual AWS account, add the account to <span class=\"ph\">RSC<\/span> using the AWS CloudFormation template. <span class=\"ph\">You add the AWS             account using the self-managed deployment model where you provision and manage compute             resources such as Exocompute in your own AWS account.<\/span><\/p>","href":"saas\/add_indv_aws_acc_using_cft_protect.html","attributes":{"data-id":"add_indv_aws_acc_using_cft_protect"},"menu":{"hasChildren":false},"tocID":"add_indv_aws_acc_using_cft_protect-d39536e16699","next":"add_indv_aws_acc_using_cft_protect-d39536e16699"},{"title":"Adding self-managed AWS accounts using AWS Organization for protection","shortdesc":"<p class=\"shortdesc\">Add multiple AWS accounts for protection using an AWS Organization. <span class=\"ph\">You add the AWS accounts using the self-managed deployment model where you provision             and manage compute resources such as Exocompute in your own AWS         accounts<\/span>.<\/p>","href":"saas\/aws_adding_acc_using_org_protection.html","attributes":{"data-id":"aws_adding_acc_using_org_protection"},"menu":{"hasChildren":false},"tocID":"aws_adding_acc_using_org_protection-d39536e16726","topics":[]},{"title":"Adding a self-managed AWS account manually for protection","shortdesc":"<p class=\"shortdesc\">To protect the AWS resources within an AWS account, add your account in <span class=\"ph\">RSC<\/span> manually by creating the required roles in the AWS Management Console         and providing the Amazon Resource Names (ARNs)         of         the required roles in <span class=\"ph\">RSC<\/span>. <span class=\"ph\">You add the             AWS account manually using the self-managed deployment model where you provision and             manage compute resources such as Exocompute in your own AWS account<\/span>.<\/p>","href":"saas\/adding_aws_account_manually_for_protection.html","attributes":{"data-id":"adding_aws_account_manually_for_protection"},"menu":{"hasChildren":false},"tocID":"adding_aws_account_manually_for_protection-d39536e16740","next":"adding_aws_account_manually_for_protection-d39536e16740"},{"title":"Adding a self-managed AWS account using a template for storage","shortdesc":"<p class=\"shortdesc\">Add the AWS account in <span class=\"ph\">RSC<\/span> using the AWS CloudFormation template for         storage. <span class=\"ph\">You add the AWS account using the self-managed deployment model             where you provision and manage compute resources such as Exocompute in your own AWS             account<\/span>.<\/p>","href":"saas\/adding_aws_cloud_account_using_cft_storage.html","attributes":{"data-id":"adding_aws_cloud_account_using_cft_storage"},"menu":{"hasChildren":false},"tocID":"adding_aws_cloud_account_using_cft_storage-d39536e16782","topics":[]},{"title":"Adding a self-managed AWS account manually for storage","shortdesc":"<p class=\"shortdesc\">Add your AWS account in <span class=\"ph\">RSC<\/span> manually for storage by creating an         cross-account role on the AWS Management Console and providing the role ARN in <span class=\"ph\">RSC<\/span>. <span class=\"ph\">You add the AWS account manually using the             self-managed deployment model where you provision and manage compute resources such as             Exocompute in your own AWS account<\/span>.<\/p>","href":"saas\/adding_aws_account_manually_storage.html","attributes":{"data-id":"adding_aws_account_manually_storage"},"menu":{"hasChildren":false},"tocID":"adding_aws_account_manually_storage-d39536e16799","topics":[]},{"title":"AWS cloud account addition using Terraform","shortdesc":"<p class=\"shortdesc\">You can add multiple AWS cloud accounts to <span class=\"ph\">RSC<\/span> at once using the <span class=\"ph\">RSC<\/span> provider for Terraform.<\/p>","href":"saas\/aws_cloud_acc_addition_terraform.html","attributes":{"data-id":"aws_cloud_acc_addition_terraform"},"menu":{"hasChildren":false},"tocID":"aws_cloud_acc_addition_terraform-d39536e16819","topics":[]},{"title":"Adding an AWS account for data scanning","shortdesc":"<p class=\"shortdesc\">Add an AWS account in <span class=\"ph\">RSC<\/span> for protection and to enable data scanning.         Data scanning helps you manage cloud posture risks.<\/p>","href":"saas\/add_aws_acc_data_scanning.html","attributes":{"data-id":"add_aws_acc_data_scanning"},"menu":{"hasChildren":false},"tocID":"add_aws_acc_data_scanning-d39536e16836","topics":[]},{"title":"Adding an AWS role chaining account","shortdesc":"<p class=\"shortdesc\">Add a dedicated AWS role chaining account in <span class=\"ph\">RSC<\/span> to centrally manage         secure access across your AWS accounts and simplify emergency revocations.<\/p>","href":"saas\/adding_aws_role_chaining_acc.html","attributes":{"data-id":"adding_aws_role_chaining_acc"},"menu":{"hasChildren":false},"tocID":"adding_aws_role_chaining_acc-d39536e16850","topics":[]},{"title":"Adding an AWS role chaining account manually","shortdesc":"<p class=\"shortdesc\">Add a dedicated AWS role chaining account in <span class=\"ph\">RSC<\/span> by manually         creating the required IAM roles in the AWS Management Console and providing the role ARN         in <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/adding_aws_role_chaining_acc_manually.html","attributes":{"data-id":"adding_aws_role_chaining_acc_manually"},"menu":{"hasChildren":false},"tocID":"adding_aws_role_chaining_acc_manually-d39536e16864","topics":[]}]}};